// ─── File: src/main/java/com/bank/security/KafkaSecurityDemo.java ───
package com.bank.security;

import java.util.*;
import java.util.logging.*;

public class KafkaSecurityDemo {
    private static final Logger log = Logger.getLogger(KafkaSecurityDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // ACLs: principal → allowed (operation:topic) pairs. Deny by default.
        Map<String, Set<String>> acls = Map.of(
            "User:settlement", Set.of("READ:transfers", "WRITE:settlement-results"),
            "User:reporting",  Set.of("READ:settlement-results")
        );
        SecurityPolicyEngine engine = new SecurityPolicyEngine(acls);

        // 1. Settlement reading transfers over mTLS from the private subnet — ALLOW
        evaluate(engine, new ConnectionRequest(
            "User:settlement", "SSL", true, "READ", "transfers", true));

        // 2. Reporting trying to WRITE transfers — DENY (no ACL)
        evaluate(engine, new ConnectionRequest(
            "User:reporting", "SSL", true, "WRITE", "transfers", true));

        // 3. Anonymous plaintext connection — DENY (not encrypted, not authenticated)
        evaluate(engine, new ConnectionRequest(
            "ANONYMOUS", "PLAINTEXT", false, "READ", "transfers", true));

        // 4. Authenticated but from outside the segmented network — DENY
        evaluate(engine, new ConnectionRequest(
            "User:settlement", "SSL", true, "READ", "transfers", false));
    }

    private static void evaluate(SecurityPolicyEngine engine, ConnectionRequest req) {
        SecurityPolicyEngine.Decision d = engine.authorize(req);
        if (d.allowed())
            log.info(() -> "ALLOW " + req.getPrincipal() + " " + req.getOperation()
                    + ":" + req.getTopic());
        else
            log.warning(() -> "DENY  " + req.getPrincipal() + " " + req.getOperation()
                    + ":" + req.getTopic() + " — " + d.reason());
    }
}

