class ConnectionRequest {
    private final String principal;
    private final String protocol;        // SSL / SASL_SSL / PLAINTEXT
    private final boolean authenticated;
    private final String operation;        // READ / WRITE / ADMIN
    private final String topic;
    private final boolean fromTrustedSubnet;
    ConnectionRequest(String principal, String protocol, boolean authenticated,
                      String operation, String topic, boolean fromTrustedSubnet) {
        this.principal = principal; this.protocol = protocol; this.authenticated = authenticated;
        this.operation = operation; this.topic = topic; this.fromTrustedSubnet = fromTrustedSubnet;
    }
    String getPrincipal() { return principal; }
    String getProtocol() { return protocol; }
    boolean isAuthenticated() { return authenticated; }
    String getOperation() { return operation; }
    String getTopic() { return topic; }
    boolean isFromTrustedSubnet() { return fromTrustedSubnet; }
}

// ─── Would be in service/SecurityPolicyEngine.java in a real project ───
class SecurityPolicyEngine {
    private final Map<String, Set<String>> acls;
    SecurityPolicyEngine(Map<String, Set<String>> acls) { this.acls = Map.copyOf(acls); }

    Decision authorize(ConnectionRequest req) {
        // Layer 1: network segmentation
        if (!req.isFromTrustedSubnet())
            return Decision.deny("connection not from a trusted segmented subnet");
        // Layer 2: encryption in transit
        if ("PLAINTEXT".equals(req.getProtocol()))
            return Decision.deny("transport not encrypted (TLS required)");
        // Layer 3: authentication
        if (!req.isAuthenticated() || "ANONYMOUS".equals(req.getPrincipal()))
            return Decision.deny("client not authenticated (mTLS/SASL required)");
        // Layer 4: authorization (ACL, deny by default)
        String needed = req.getOperation() + ":" + req.getTopic();
        Set<String> allowed = acls.getOrDefault(req.getPrincipal(), Set.of());
        if (!allowed.contains(needed))
            return Decision.deny("no ACL grants " + needed + " to " + req.getPrincipal());
        return Decision.allow();
    }

    // simple immutable decision value object
    static final class Decision {
        private final boolean allowed;
        private final String reason;
        private Decision(boolean allowed, String reason) { this.allowed = allowed; this.reason = reason; }
        static Decision allow() { return new Decision(true, "ok"); }
        static Decision deny(String reason) { return new Decision(false, reason); }
        boolean allowed() { return allowed; }
        String reason() { return reason; }
    }
}

